#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_N 100
#define MAX_VAL 255
#define MIN_VAL 0
#define START_VAL 128
#define INF 1000000000

int main() {
    int n;
    int a[MAX_N];
    int codebook[256];
    int codebook_size = 0;

    // Read codebook values (0-255)
    char line[1024];
    fgets(line, sizeof(line), stdin);
    char *token = strtok(line, " \n");
    while (token) {
        codebook[codebook_size++] = atoi(token);
        token = strtok(NULL, " \n");
    }

    // Read number of samples
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    // dp[i][v] = minimum sum of squared differences for first i samples,
    //            ending with output value v (0-255)
    int dp[MAX_N + 1][256];
    for (int i = 0; i <= n; i++) {
        for (int v = 0; v <= 255; v++) {
            dp[i][v] = INF;
        }
    }

    // Initial condition: output starts at 128
    dp[0][START_VAL] = 0;

    for (int i = 0; i < n; i++) {
        for (int prev = 0; prev <= 255; prev++) {
            if (dp[i][prev] == INF) continue;
            // Try each codebook value as the difference to apply
            for (int c = 0; c < codebook_size; c++) {
                int next_val = prev + codebook[c];
                // Clip to [0, 255]
                if (next_val < 0) next_val = 0;
                if (next_val > 255) next_val = 255;
                int diff = a[i] - next_val;
                int cost = dp[i][prev] + diff * diff;
                if (cost < dp[i + 1][next_val]) {
                    dp[i + 1][next_val] = cost;
                }
            }
        }
    }

    // Find minimum over all possible ending values
    int ans = INF;
    for (int v = 0; v <= 255; v++) {
        if (dp[n][v] < ans) {
            ans = dp[n][v];
        }
    }

    printf("%d\n", ans);

    return 0;
}

