static inline int clip(int x) {
    if (x < 0) return 0;
    if (x > 255) return 255;
    return x;
}

int main(void) {
    int n, m;
    while (scanf("%d %d", &n, &m) == 2) {
        int *a = (int *)malloc(n * sizeof(int));
        int *code = (int *)malloc(m * sizeof(int));
        if (!a || !code) return 0;

        for (int i = 0; i < n; i++) scanf("%d", &a[i]);
        for (int i = 0; i < m; i++) scanf("%d", &code[i]);

        int dp_prev[256], dp_cur[256];

        for (int v = 0; v < 256; v++) dp_prev[v] = INF;
        dp_prev[128] = 0;

        for (int i = 0; i < n; i++) {
            for (int v = 0; v < 256; v++) dp_cur[v] = INF;

            for (int prev = 0; prev < 256; prev++) {
                if (dp_prev[prev] == INF) continue;
                for (int j = 0; j < m; j++) {
                    int now = clip(prev + code[j]);
                    int diff = a[i] - now;
                    int cost = dp_prev[prev] + diff * diff;
                    if (cost < dp_cur[now]) dp_cur[now] = cost;
                }
            }

            for (int v = 0; v < 256; v++) dp_prev[v] = dp_cur[v];
        }

        int ans = INF;
        for (int v = 0; v < 256; v++) {
            if (dp_prev[v] < ans) ans = dp_prev[v];
        }

        printf("%d\n", ans);

        free(a);
        free(code);
    }
    return 0;
}

