        vector<vector<int>> dp(n, vector<int>(256, INF));

        // Initialize for first element
        for (int v = 0; v <= 255; v++) {
            int diff = (128 + c[0]) - x[0];
            dp[0][v] = diff * diff;
        }

        for (int i = 1; i < n; i++) {
            for (int prev = 0; prev <= 255; prev++) {
