                    if (next_val < 0) next_val = 0;
                    if (next_val > 255) next_val = 255;
                    int diff = next_val - x[i];
                    int cost = dp[i-1][prev] + diff * diff;
                    if (cost < dp[i][next_val]) {
                        dp[i][next_val] = cost;
                    }
                }
