int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const vector<int> codebook = {-16, -8, -4, -2, -1, 0, 1, 2, 4, 8, 16};

    int P;
    while (cin >> P && P) {
        vector<int> a(P);
        for (int i = 0; i < P; ++i) cin >> a[i];

        const long long INF = (1LL << 60);
        vector<long long> dp(256, INF), ndp(256, INF);

        dp[128] = 0; // starting decoded value

        for (int i = 0; i < P; ++i) {
            fill(ndp.begin(), ndp.end(), INF);
            for (int v = 0; v <= 255; ++v) {
                if (dp[v] == INF) continue;
                for (int d : codebook) {
                    int nv = clip(v + d);
                    long long cost = 1LL * (a[i] - nv) * (a[i] - nv);
                    ndp[nv] = min(ndp[nv], dp[v] + cost);
                }
            }
            dp.swap(ndp);
        }

        long long ans = *min_element(dp.begin(), dp.end());
        cout << ans << '\n';
    }

    return 0;
}

