public class Main {
    static final int START = 128;
    static final int MIN_VAL = 0;
    static final int MAX_VAL = 255;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            int N = Integer.parseInt(line);
            if (N == 0) break;

            int[] original = new int[N];
            for (int i = 0; i < N; i++) {
                original[i] = Integer.parseInt(br.readLine().trim());
            }

            // Read codebook size
            int M = Integer.parseInt(br.readLine().trim());
            int[] codebook = new int[M];
            for (int i = 0; i < M; i++) {
                codebook[i] = Integer.parseInt(br.readLine().trim());
            }

            // DP array: dp[i][v] = min cost for first i samples ending with output value v
            // Since values are between 0 and 255, we can use array size 256
            long[][] dp = new long[N + 1][MAX_VAL + 1];
            final long INF = Long.MAX_VALUE / 2;

            // Initialize
            for (int v = MIN_VAL; v <= MAX_VAL; v++) {
                dp[0][v] = INF;
            }
            dp[0][START] = 0;

            // Precompute possible next values for each current value
            // For each possible current output value, we can add any codebook value (clipped)

            for (int i = 0; i < N; i++) {
                // Reset next row
                Arrays.fill(dp[i + 1], INF);

                for (int cur = MIN_VAL; cur <= MAX_VAL; cur++) {
                    if (dp[i][cur] == INF) continue;

                    for (int d : codebook) {
                        int next = cur + d;
                        if (next < MIN_VAL) next = MIN_VAL;
                        if (next > MAX_VAL) next = MAX_VAL;

                        long cost = dp[i][cur] + (long)(original[i] - next) * (original[i] - next);
                        if (cost < dp[i + 1][next]) {
                            dp[i + 1][next] = cost;
                        }
                    }
                }
            }

            // Find minimum cost after processing all samples
            long answer = INF;
            for (int v = MIN_VAL; v <= MAX_VAL; v++) {
                if (dp[N][v] < answer) {
                    answer = dp[N][v];
                }
            }

            System.out.println(answer);
        }
    }
}

