public class Main {
    static final int STATES = 256;
    static final long INF = Long.MAX_VALUE / 4;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            Integer nObj = fs.nextIntNullable();
            if (nObj == null) break;
            int n = nObj;
            if (n == 0) break;

            int[] signal = new int[n];
            for (int i = 0; i < n; i++) signal[i] = fs.nextInt();

            int m = fs.nextInt();
            int[] codebook = new int[m];
            for (int i = 0; i < m; i++) codebook[i] = fs.nextInt();

            long[] dp = new long[STATES];
            long[] next = new long[STATES];
            Arrays.fill(dp, INF);

            // Starting decoded value is 128 before any output is produced.
            dp[128] = 0;

            for (int i = 0; i < n; i++) {
                Arrays.fill(next, INF);

                for (int prev = 0; prev < STATES; prev++) {
                    long curCost = dp[prev];
                    if (curCost == INF) continue;

                    for (int d : codebook) {
                        int val = prev + d;
                        if (val < 0) val = 0;
                        else if (val > 255) val = 255;

                        long diff = signal[i] - val;
                        long cost = curCost + diff * diff;
                        if (cost < next[val]) next[val] = cost;
                    }
                }

                long[] temp = dp;
                dp = next;
                next = temp;
            }

            long ans = INF;
            for (int v = 0; v < STATES; v++) ans = Math.min(ans, dp[v]);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextIntNullable() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return nextIntNullable();
        }
    }
}

