import sys

def solve():
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return

    it = iter(data)
    out = []

    while True:
        try:
            n = next(it)
        except StopIteration:
            break

        if n == 0:
            break

        signal = [next(it) for _ in range(n)]
        m = next(it)
        codebook = [next(it) for _ in range(m)]

        INF = 10**18

        # dp[v] = minimum cost after processing current prefix,
        # ending with decoded value v
        dp = [INF] * 256
        dp[128] = 0  # starting decoded value

        for x in signal:
            ndp = [INF] * 256
            for v in range(256):
                cur = dp[v]
                if cur == INF:
                    continue
                for d in codebook:
                    nv = v + d
                    if nv < 0:
                        nv = 0
                    elif nv > 255:
                        nv = 255
                    cost = cur + (x - nv) * (x - nv)
                    if cost < ndp[nv]:
                        ndp[nv] = cost
            dp = ndp

        out.append(str(min(dp)))

    sys.stdout.write("\n".join(out))

